   "titulo": "Nueva York veta juguetes con agentes de IA integrados",
   "resumen": "La ley se centra en juguetes como peluches, muñecas o robots que usan chatbots de IA, conectados a internet, para hablar con niños de muy baja edad.",
   "fuente": "RPP",
   "url": "https://rpp.pe/mundo/estados-unidos/nueva-york-veta-juguetes-con-agentes-de-ia-integrados-noticia-1719658",
   "fecha": "2026-11-25T12:30:25Z",
   "tipo": "comercial",
