   "sintesis": "«Si algo me ha enseñado la experiencia es que los bribones no se vuelven honrados milagrosamente con la edad. A primera vista, cualquiera diría que estas palabras pertenecen al guion de una película de bajo presupuesto o a una de esas telenovelas disparatadas.",
   "puntos": [
    "«Si algo me ha enseñado la experiencia es que los bribones no se vuelven honrados milagrosamente con la edad.",
    "A primera vista, cualquiera diría que estas palabras pertenecen al guion de una película de bajo presupuesto o a una de esas telenovelas disparatadas.",
    "La frase la escribió John MacNamara en un correo electrónico de octubre de 2018, cuando ocupaba el cargo de director global de materias primas de Deutsche Bank (DB), uno de los mayores bancos del mundo, con presencia en Brasil desde hace más de un siglo."
   ],
